import java.io.* ;

import java.util.*;

public class ghh {

	static int n ; 
	static long occ[] ; 
	static long nbr_vertexes[] ;
	static long big = (long) (1e9 + 7) ;
	static void count_vertexes()
	{
		occ[0]++ ; 
		nbr_vertexes[0]=1 ;
		for(int i=1 ;i<=n ;i++)
		{
			long oc[] = new long[n/2 +1] ; 
			int limite = Integer.min(n-i, n/2); 
			for(int j=0 ;j<=limite; j++)
			{
				long h = occ[j] ;
				if(j+1<=limite)
					{
					oc[j+1]+=(h) ;oc[j+1]%=big  ;
					}
				if(j-1>=0) 
					{
					oc[j-1]+=h ; oc[j-1]%=big  ;
					}
				oc[j]%=big  ;
			}
			if(limite+1<=n/2)
				{
				oc[limite]+=occ[limite+1] ;
				oc[limite]%=big ;
				}
			long sum=0 ; 
			for(int j=0 ;j<=limite; j++)
			{ 
				sum+= (oc[j]) ; 
				occ[j]=oc[j] ;
				sum = sum%big ; 
			}
			nbr_vertexes[i]=sum ; 	
		}

	}


	public static void main(String[] args) throws IOException {

		BufferedReader jk = new BufferedReader(new InputStreamReader(System.in)) ;
		PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out)) ;
		StringTokenizer ana =new StringTokenizer(jk.readLine()) ;
		n = Integer.parseInt(ana.nextToken()) ;  
		n= 2*n ;
		occ = new long[n/2+1] ;
		nbr_vertexes = new long[n+1] ;
		long res1 = 0 ;
		long res2 = 0 ;
		count_vertexes();
		for(int i= n-1 ;i>=0 ; i-=2) 
		{

			res1+=nbr_vertexes[i] ; 
			res1%=big ;
		}
		for(int i= n-2 ;i>=0 ; i-=2) 
		{
			res2+=nbr_vertexes[i] ; 
			res2%=big ; 
		}
		out.println(res1);


		out.flush();
	}


}


